# Tree Tree Многоуровневый раскрывающийся список в виде дерева с возможностью выбора (selection) и выделения (checkbox). Обязательным параметром является только массив  `items` . Формат следующий: ```tsx
type TreeItem = {
    /**
     * Уникальный идентификатор элемента.
     */
    key: React.Key;
    /**
     * Заголовок элемента.
     */
    title?: React.ReactNode | ((data: TreeItem) => React.ReactNode);
    /**
     * Classname для текущего элемента.
     */
    className?: string;
    /**
     * Стиль для текущего элемента.
     */
    style?: React.CSSProperties;
    /**
     * Флаг выключения элемента.
     * @default false
     */
    disabled?: boolean;
    /**
     * Иконка для текущего элемента.
     */
    icon?: React.ReactNode;
    /**
     * Дочерние items.
     */
    children?: TreeItem[];
    /**
     * Контент справа.
     */
    contentRight?: React.ReactNode;
};
```

## Примеры Примеры ```tsx
